--
-- Auction bot price table (mod-ah-bot-plus): the buyout price of one unit of each item, taken from the
-- expansion the item was added in, so that original items cost what they did in 2006, Burning Crusade
-- items what they did in 2007-2008 and Wrath items what they did in 2009-2010.
--
-- era:    0 original, 1 Burning Crusade, 2 Wrath of the Lich King
-- price:  copper per unit
-- source: 0 median of archived Allakhazam medians, 1 Enchantrix StaticPrices, 2 estimate from similar
--         items of the same era, 3 set by hand (rows with source 3 survive a regenerated table)
--
-- Generated by C:\ServersGit\tools\ah-prices\build_table.py
--
CREATE TABLE IF NOT EXISTS `mod_ahbot_item_price` (
  `item` INT UNSIGNED NOT NULL,
  `era` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 original, 1 TBC, 2 WotLK',
  `price` INT UNSIGNED NOT NULL COMMENT 'buyout of one unit, copper',
  `source` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 archive, 1 Enchantrix, 2 estimate, 3 manual',
  `samples` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'archive snapshots behind the price',
  PRIMARY KEY (`item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='mod-ah-bot-plus: era prices';

DELETE FROM `mod_ahbot_item_price` WHERE `source` <> 3;
